// 复现 _mComputeOne('000999') 失败原因：逐步调试每一步网络请求
const https = require('https');
function get(u) {
  return new Promise((res, rej) => {
    const r = https.get(u, { headers: { 'User-Agent': 'Mozilla/5.0', 'Referer': 'https://quote.eastmoney.com/' } }, x => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); return get(x.headers.location).then(res, rej); }
      const c = []; x.on('data', d => c.push(d)); x.on('end', () => res({ code: x.statusCode, body: Buffer.concat(c).toString('utf8') }));
    });
    r.on('error', rej); r.setTimeout(20000, () => r.destroy(new Error('timeout')));
  });
}
const CODE = '000999', SECID = '0.000999';
function shift(days) { return new Date(Date.now() + days * 864e5).toISOString().slice(0, 10).replace(/-/g, ''); }

(async () => {
  const beg = shift(-(3 * 365 + 40));
  console.log('beg =', beg);

  for (const fqt of [1, 0]) {
    const u = 'https://push2his.eastmoney.com/api/qt/stock/kline/get?secid=' + SECID +
      '&fields1=f1,f2,f3,f4,f5&fields2=f51,f52,f53,f54,f55,f56&klt=101&fqt=' + fqt + '&beg=' + beg + '&end=20500101';
    try {
      const r = await get(u);
      let j = null;
      try { j = JSON.parse(r.body); } catch (e) {}
      const n = j && j.data && j.data.klines ? j.data.klines.length : 0;
      console.log('kline fqt=' + fqt + '  HTTP=' + r.code + '  klines=' + n + (n === 0 ? '  ⚠ 空!' : ''));
      if (n === 0) console.log('   body head:', r.body.slice(0, 200));
    } catch (e) { console.log('kline fqt=' + fqt + ' ERR:', e.message); }
  }

  const du = 'https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_SHAREBONUS_DET&columns=ALL&filter=(SECURITY_CODE%3D%22' + CODE + '%22)&pageNumber=1&pageSize=100&sortColumns=EX_DIVIDEND_DATE&sortTypes=-1';
  try {
    const r = await get(du);
    const j = JSON.parse(r.body);
    const n = j && j.result && j.result.data ? j.result.data.length : 0;
    console.log('dividend HTTP=' + r.code + '  rows=' + n);
  } catch (e) { console.log('dividend ERR:', e.message); }
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

